      stg_presetTerminalFirstText: 'Método obligatorio en cada tarea de construcción o desarrollo:\n1) Usar la terminal automáticamente en cada etapa: crear las carpetas del proyecto con comandos reales y, después de cada etapa, mostrar la estructura de archivos.\n2) Después de escribir cualquier archivo, comprobarlo desde la terminal (mostrar su tamaño y sus primeras líneas).\n3) Antes de anunciar que algo está terminado, ejecutar comprobaciones reales desde la terminal y mostrar su salida completa en la pestaña Terminal.\n4) Si un comando falla: leer el error, corregir la causa y volver a intentarlo; nunca pasar por alto un error.\n5) No decir «el trabajo está terminado» hasta que todas las comprobaciones hayan pasado, con un resumen de los comandos ejecutados.',
